  "program.explain.blockRationale": "Þetta er {{weeks}} vikna áætlun. Í viku {{reviewWeek}} biðjum við þig um að meta hvernig æfingarnar gengu, hvar framfarir urðu og hvort breyta eigi dögum eða æfingum.",
  "program.explain.calibrationCue": "Finna byrjunarþyngd: byrjaðu létt og þyngdu í litlum skrefum þar til þú gætir gert um 2–3 endurtekningar í viðbót. Skráðu þá þyngd sem byrjunarþyngd.",
  "program.explain.calibrationNote": "Fyrsta æfingin er létt og notuð til að finna byrjunarþyngd. Þú þarft ekki að þekkja hámarksþyngdina þína.",
  "program.explain.calibrationRationale": "Þú þarft ekki að þekkja hámarksþyngdina þína í einni endurtekningu. Ef hæfileg byrjunarþyngd er ekki þekkt finnurðu hana í léttri fyrstu æfingu: byrjaðu létt og þyngdu í litlum skrefum þar til þú gætir gert um 2–3 endurtekningar í viðbót. Við giskum aldrei á byrjunarþyngd út frá aldri eða líkamsþyngd.",
  "program.explain.durationRationale": "Áætlaður æfingatími tekur með 5 mínútna almenna upphitun, undirbúning, stigvaxandi upphitunarsett og hvíld milli setta.",
  "program.explain.limitationRationale": "Við slepptum æfingum sem reyna oft á þessi svæði: {{areas}}. Þetta er ekki greining. Þú getur bætt æfingu sem þér líkar aftur við ef hún veldur engum óþægindum. Leitaðu til heilbrigðisstarfsfólks ef verkir eru viðvarandi.",
  "program.explain.prescription": "{{sets}} × {{reps}} · RIR {{rir}} · hvíld {{rest}}",
  "program.explain.repRange": "{{min}}–{{max}}",
  "program.explain.repsBeginner": "Aðallyftur byrja á 5–8 endurtekningum svo þú getir æft tæknina áður en þú þyngir. Viðbótaræfingar nota 10–15 endurtekningar. Þetta eru sjálfgefin viðmið í appinu sem má breyta.",
  "program.explain.repsDefault": "Flestar lyftur nota um 8–12 endurtekningar og viðbótaræfingar 10–15. Það hentar vel til að byggja upp vöðva. Þetta eru sjálfgefin viðmið sem má breyta; aðrir kostir geta líka virkað vel.",
  "program.explain.repsEndurance": "Styrktaræfingar nota 8–12 endurtekningar og viðbótaræfingar 12–15 svo þær styðji við aðalhreyfinguna án mikilla harðsperra. Þetta eru sjálfgefin viðmið sem má breyta.",
  "program.explain.repsStrength": "Aðallyftur nota færri endurtekningar (3–6) til að auka styrk, stoðæfingar miðlungsfjölda og viðbótaræfingar fleiri endurtekningar. Þetta eru sjálfgefin viðmið í appinu sem má breyta.",
  "program.explain.restMinutes": "{{minutes}} mín.",
  "program.explain.restMinutesSeconds": "{{minutes}}:{{secondsPadded}} mín.",
  "program.explain.restSeconds": "{{seconds}} sek.",
  "program.explain.rir": "RIR merkir „endurtekningar í varasjóði“. Hættu hverju setti þegar þú gætir enn gert um það bil þennan fjölda endurtekninga. RIR 2–3 merkir að þú hefðir getað gert 2–3 endurtekningar í viðbót með góðri tækni.",
  "program.explain.rirMany": "hættu þegar þú gætir enn gert um {{count}} endurtekningar",
  "program.explain.rirOne": "hættu þegar þú gætir enn gert um eina endurtekningu",
  "program.explain.rirZero": "farðu nálægt mörkunum þínum",
  "program.explain.seconds": "{{seconds}} sek.",
  "program.explain.sessionCalibration": "Þar sem stendur „finna byrjunarþyngd“: byrjaðu létt og þyngdu í litlum skrefum þar til þú gætir gert 2–3 endurtekningar í viðbót. Skráðu þá þyngd sem byrjunarþyngd.",
