  "program.rationale.beginnerFiveDays": "Með litla reynslu eða eftir hlé gefa 4 dagar, skiptir milli efri og neðri líkama, yfirleitt betri tíma til endurheimtar. Við settum upp 5 daga áætlunina sem þú valdir. Íhugaðu 4 daga ef þreyta safnast upp.",
