  "program.split.es.description": "Stuttar styrktaræfingar fyrir allan líkamann sem styðja við aðalhreyfinguna þína: fætur, mjaðmir, bolur og líkamsstaða.",
  "program.split.es.label": "Styrkur til stuðnings",
  "program.split.fallbackEndurance.one": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardag til stuðnings úthaldi. Áætlunin notar því líkustu skiptinguna: {{actualSplit}}.",
  "program.split.fallbackEndurance.other": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardaga til stuðnings úthaldi. Áætlunin notar því líkustu skiptinguna: {{actualSplit}}.",
  "program.split.fallbackLifting.one": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardag. Áætlunin notar því líkustu skiptinguna: {{actualSplit}}.",
  "program.split.fallbackLifting.other": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardaga. Áætlunin notar því líkustu skiptinguna: {{actualSplit}}.",
  "program.split.fb1.description": "Ein æfing fyrir allan líkamann sem nær yfir öll helstu hreyfimynstur.",
  "program.split.fb1.label": "Allur líkaminn",
  "program.split.fb2.description": "Tvær æfingar fyrir allan líkamann (A og B) svo hver stór vöðvahópur sé þjálfaður tvisvar í viku.",
  "program.split.fb2.label": "Allur líkaminn A/B",
  "program.split.fb3.description": "Þrjár æfingar fyrir allan líkamann (A, B og C). Þú æfir aðallyfturnar oft en gerir færri æfingar í hvert sinn.",
  "program.split.fb3.label": "Allur líkaminn A/B/C",
  "program.split.fb4.description": "Fjórar styttri æfingar fyrir allan líkamann. Allar aðallyftur eru æfðar oft en færri æfingar gerðar í hvert sinn.",
  "program.split.fb4.label": "Allur líkaminn ×4",
  "program.split.ppl3.description": "Einn dagur fyrir pressur, einn fyrir togæfingar og einn fyrir fætur. Mikil vinna fyrir hvern vöðvahóp, sem er þjálfaður einu sinni í viku.",
  "program.split.ppl3.label": "Pressur / tog / fætur",
  "program.split.ppl6.description": "Pressur, togæfingar og fætur tvisvar hvert í viku. Tíðar æfingar og mikið æfingamagn fyrir fólk með reynslu.",
  "program.split.ppl6.label": "Pressur / tog / fætur ×2",
  "program.split.recommendedEndurance.one": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardag til stuðnings úthaldi. Áætlunin notar því ráðlagða skiptingu: {{actualSplit}}. Þú getur valið aðra skiptingu.",
  "program.split.recommendedEndurance.other": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardaga til stuðnings úthaldi. Áætlunin notar því ráðlagða skiptingu: {{actualSplit}}. Þú getur valið aðra skiptingu.",
  "program.split.recommendedLifting.one": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardag. Áætlunin notar því ráðlagða skiptingu: {{actualSplit}}. Þú getur valið aðra skiptingu.",
  "program.split.recommendedLifting.other": "Skiptingin „{{requestedSplit}}“ passar ekki við {{count}} styrktardaga. Áætlunin notar því ráðlagða skiptingu: {{actualSplit}}. Þú getur valið aðra skiptingu.",
  "program.split.tradeoff.es1": "Ein stutt æfing fyrir allan líkamann með áherslu á fætur, mjaðmir, bol og líkamsstöðu.",
  "program.split.tradeoff.es2": "Tvær stuttar æfingar fyrir allan líkamann sem styðja við aðalhreyfinguna þína án þess að þreyta fæturna mikið á einum degi.",
  "program.split.tradeoff.esUpperLower": "Fætur og mjaðmir fá eina markvissa æfingu. Hinn styrktardagurinn þreytir því ekki fæturna fyrir mikilvægustu æfingarnar.",
  "program.split.tradeoff.fb1": "Ein æfing sem nær yfir allar helstu hreyfingar. Eina skiptingin sem nær yfir allt á einum degi.",
  "program.split.tradeoff.fb2": "Hver vöðvahópur tvisvar í viku. Þótt ein æfing falli niður færðu samt æfingu fyrir allan líkamann.",
  "program.split.tradeoff.fb3": "Aðallyfturnar æfðar þrisvar í viku í styttri æfingum. Auðveldasta skiptingin að jafna sig á milli æfinga.",
  "program.split.tradeoff.fb4": "Fjórar styttri æfingar fyrir allan líkamann. Allar lyftur æfðar oft; hentar þegar tíminn er knappur.",
  "program.split.tradeoff.newer": "Fólk með litla reynslu nær yfirleitt fyrr tökum á lyftunum með tíðari æfingum.",
  "program.split.tradeoff.ppl3": "Mest vinna fyrir hvern vöðva í hvert sinn en hver vöðvahópur þjálfaður einu sinni í viku. Ef dagur fellur niður missir heill líkamshluti af æfingu.",
  "program.split.tradeoff.ppl6": "Pressur, togæfingar og fætur tvisvar hvert. Mikið æfingamagn sem krefst góðs svefns og endurheimtar.",
  "program.split.tradeoff.ul2": "Meiri vinna fyrir hvern vöðva í hvert sinn en hver vöðvahópur þjálfaður einu sinni í viku.",
  "program.split.tradeoff.ul4": "Hver vöðvahópur tvisvar í viku í markvissum æfingum, með hvíldardegi fyrir hvorn helming líkamans.",
  "program.split.tradeoff.ul5": "Efri og neðri líkami tvisvar hvor ásamt degi fyrir allan líkamann. Hver vöðvahópur tvisvar í viku með almennari æfingadögum.",
  "program.split.tradeoff.ul6": "Efri og neðri líkami þrisvar hvor. Tíðar æfingar með hóflegu æfingamagni í hvert sinn.",
  "program.split.tradeoff.ulf": "Einn dagur fyrir efri líkamann, einn fyrir þann neðri og einn fyrir allan líkamann. Meiri vinna í hvert sinn og efri og neðri líkaminn þjálfaðir tvisvar hvor.",
  "program.split.tradeoff.ulppl": "Efri og neðri líkami ásamt pressum, togæfingum og fótum. Tíðar æfingar og mikið æfingamagn.",
  "program.split.tradeoff.ulpplNewer": "Getur verið erfitt að ná endurheimt milli æfinga með litla reynslu.",
  "program.split.ul2.description": "Ein æfing fyrir efri líkamann og ein fyrir þann neðri. Meiri vinna fyrir hvern vöðva í hvert sinn en hver vöðvahópur þjálfaður einu sinni í viku.",
  "program.split.ul2.label": "Efri / neðri líkami",
  "program.split.ul4.description": "Æfingar fyrir efri og neðri líkamann tvisvar hvor svo hver vöðvahópur sé þjálfaður tvisvar í viku og fái tíma til að jafna sig.",
  "program.split.ul4.label": "Efri / neðri líkami ×2",
  "program.split.ul5.description": "Efri og neðri líkami tvisvar hvor ásamt einum degi fyrir allan líkamann. Hver vöðvahópur tvisvar í viku og aukadagur til að æfa aðallyfturnar.",
  "program.split.ul5.label": "Efri / neðri líkami ×2 + allur líkaminn",
  "program.split.ul6.description": "Efri og neðri líkami þrisvar hvor. Tíðar æfingar með hóflegu æfingamagni í hvert sinn.",
  "program.split.ul6.label": "Efri / neðri líkami ×3",
  "program.split.ulf.description": "Einn dagur fyrir efri líkamann, einn fyrir þann neðri og einn fyrir allan líkamann. Meira æfingamagn fyrir hvern vöðva í hvert sinn, fyrir fólk með reynslu.",
  "program.split.ulf.label": "Efri / neðri / allur líkaminn",
  "program.split.ulppl.description": "Efri og neðri líkami ásamt dögum fyrir pressur, togæfingar og fætur. Tíðar æfingar fyrir fólk með reynslu.",
  "program.split.ulppl.label": "Efri / neðri líkami + pressur / tog / fætur",
