  "recipe.step.spanish-chickpea-potato-stew.1": "Mýktu laukinn og hvítlaukinn í olíunni í stórum potti í 5 mínútur.",
  "recipe.step.spanish-chickpea-potato-stew.2": "Hrærðu paprikukryddinu og broddkúmeninu saman við og bættu svo kartöflunum, tómötunum og 500 ml af vatni við.",
