  "recipe.step.spiced-lamb-rice-bowl.4": "Settu í skál og bættu gúrkunni og sítrónujógúrtinni ofan á.",
  "recipe.step.spiced-lentil-wrap.1": "Hitaðu linsubaunirnar með kryddinu og smá vatni á pönnu í 4 mínútur og stappaðu nokkrar þeirra.",
