  "recipe.step.spiced-lentil-wrap.3": "Bættu linsubaununum, salatinu, tómatnum og graskersfræjunum við og rúllaðu svo upp.",
  "recipe.step.spinach-feta-frittata.1": "Hitaðu olíuna á pönnu sem má fara í ofn og eldaðu kartöflurnar og laukinn undir loki við miðlungshita í 10 mínútur þar til allt er mjúkt.",
