  "recipe.step.spinach-feta-frittata.4": "Eldaðu í 4 mínútur þar til botninn stífnar og kláraðu undir heitu ofngrilli í 4–5 mínútur þar til rétturinn hefur lyft sér og er gullinbrúnn.",
  "recipe.step.spinach-ricotta-pasta-bake.1": "Hitaðu ofninn í 200 °C. Sjóððu pastað í 2 mínútur skemur en stendur á umbúðunum og helltu vatninu af.",
