  "recipe.step.squid-green-bean-stir-fry.3": "Bættu engiferinu, hvítlauknum og smokkfiskinum við og snöggsteiktu við háan hita í 2–3 mínútur.",
  "recipe.step.squid-green-bean-stir-fry.4": "Helltu sojasósunni út á, blandaðu saman og berðu fram á hrísgrjónunum.",
