  "recipe.step.tofu-fajita-traybake.4": "Fylltu tortillurnar með tófúinu og grænmetinu og settu jógúrtina ofan á.",
  "recipe.step.tofu-scramble-peppers.1": "Steiktu laukinn og paprikuna í olíunni í 4 mínútur þar til þau mýkjast.",
