  "recipe.step.tofu-shakshuka-rye.3": "Leggðu tófúsneiðarnar í sósuna, settu lok á og láttu malla í 5 mínútur þar til þær eru heitar í gegn.",
  "recipe.step.tofu-shakshuka-rye.4": "Berðu fram beint af pönnunni með rúgbrauði til að dýfa í sósuna.",
  "recipe.step.tofu-sweet-potato-curry-batch.1": "Settu hrísgrjónin yfir. Mýktu laukinn í smá vatni í stórum potti í 4 mínútur.",
  "recipe.step.tofu-sweet-potato-curry-batch.2": "Hrærðu karríduftinu saman við og bættu svo sætu kartöflunum, kókosmjólkinni og 150 ml af vatni við.",
  "recipe.step.tofu-sweet-potato-curry-batch.3": "Láttu malla í 12 mínútur þar til kartöflurnar eru næstum mjúkar, bættu svo tófúinu við og láttu malla í 6 mínútur til viðbótar.",
  "recipe.step.tofu-sweet-potato-curry-batch.4": "Hrærðu spínatinu saman við þar til það fellur saman, kryddaðu og berðu fram á hrísgrjónunum.",
  "recipe.step.tofu-tikka-wrap.1": "Veltu tófúinu upp úr helmingnum af jógúrtinni, kryddinu og sítrónusafanum.",
  "recipe.step.tofu-tikka-wrap.2": "Steiktu á þurri viðloðunarfrírri pönnu í 8 mínútur, snúðu reglulega við, þar til brúnirnar eru vel brúnaðar.",
  "recipe.step.tofu-tikka-wrap.3": "Hitaðu tortilluna, smyrðu afganginum af jógúrtinni á hana og bættu salati og gúrku við.",
  "recipe.step.tofu-tikka-wrap.4": "Settu tófúið ofan á, rúllaðu þétt upp og skerðu í tvennt.",
  "recipe.step.tofu-veg-stir-fry.1": "Sjóddu hrísgrjónin samkvæmt leiðbeiningum á pakkanum.",
  "recipe.step.tofu-veg-stir-fry.2": "Steiktu tófúið í helmingnum af olíunni við háan hita í 6–8 mínútur og snúðu því þar til það er gullinbrúnt. Settu til hliðar.",
  "recipe.step.tofu-veg-stir-fry.3": "Steiktu grænmetið og edamame-baunirnar í restinni af olíunni í 4 mínútur og hrærðu á meðan. Bættu hvítlauknum við og steiktu í 30 sekúndur.",
  "recipe.step.tofu-veg-stir-fry.4": "Settu tófúið aftur á pönnuna, bættu sojasósunni við, blandaðu saman og berðu fram yfir hrísgrjónunum.",
  "recipe.step.tuna-black-bean-breakfast-burrito.1": "Hrærðu egginu á viðloðunarfrírri pönnu með baununum og kryddinu í 2 mínútur.",
  "recipe.step.tuna-black-bean-breakfast-burrito.2": "Hrærðu túnfiskinum og tómatnum saman við þar til allt er heitt.",
  "recipe.step.tuna-black-bean-breakfast-burrito.3": "Settu fyllinguna á tortilluna með skeið, rúllaðu þétt upp og ristaðu með samskeytin niður í 1 mínútu.",
  "recipe.step.tuna-chickpea-salad.1": "Hrærðu olíunni og sítrónusafanum saman við salt og pipar í stórri skál.",
  "recipe.step.tuna-chickpea-salad.2": "Bættu kjúklingabaununum, grænmetinu og lauknum við og blandaðu vel saman.",
  "recipe.step.tuna-chickpea-salad.3": "Losaðu túnfiskinn í bita, blandaðu varlega saman við og berðu fram á salatblöðunum.",
  "recipe.step.tuna-crispbreads.1": "Blandaðu túnfiskinum saman við skyrið og piparinn.",
  "recipe.step.tuna-crispbreads.2": "Smyrðu á hrökkbrauðið og settu gúrku ofan á.",
  "recipe.step.tuna-edamame-quinoa-bowl.1": "Settu kínóað í skál.",
  "recipe.step.tuna-edamame-quinoa-bowl.2": "Settu túnfiskinn, edamame-baunirnar, gulrótina og gúrkuna ofan á.",
  "recipe.step.tuna-edamame-quinoa-bowl.3": "Þeyttu límónusafann, sesamolíuna og chili-flögurnar saman og helltu yfir.",
  "recipe.step.tuna-egg-fried-rice.1": "Hitaðu olíuna á wok-pönnu, bættu eggjunum við og hrærðu þar til þau eru rétt stífnuð. Ýttu til hliðar.",
  "recipe.step.tuna-egg-fried-rice.2": "Bættu hrísgrjónunum og grænu baununum við og snöggsteiktu í 4 mínútur þar til allt er heitt.",
