  "settings.about": "Um appið, formúlur og heimildir",
  "settings.about1rm": "Áætlað 1RM byggir á Epley-formúlunni og birtist aðeins fyrir æfingar með ytri þyngd og 1–10 endurtekningum.",
  "settings.aboutBrand": "Um {{brand}}",
  "settings.aboutEnergy": "Orkuþörf í hvíld: Mifflin–St Jeor-jafnan (Mifflin o.fl., 1990). Stuðlar fyrir hreyfingu og aðlögun að markmiðum eru forsendur sem má breyta.",
  "settings.aboutExercise": "Lýsingar á æfingum eru frumsamdar. Ekki eru notaðar æfingamyndir frá þriðja aðila.",
  "settings.aboutFood": "Næringargildi matvæla: áætluð almenn gildi byggð á USDA FoodData Central. Skoðaðu alltaf umbúðamerkingar og upplýsingar um ofnæmisvalda.",
  "settings.aboutIdea": "Hugmyndin að baki {{brand}} er einföld: vinnan sem þú leggur í æfingar á skilið góða skráningu. Skráningin á að nýtast þér, hvort sem þú ert að stíga fyrstu skrefin eða vinna að markmiði sem þú hefur lengi stefnt að.",
  "settings.aboutProtein": "Prótein: 1,6–2,2 g á hvert kg viðmiðunarþyngdar á dag er hagnýtt viðmið fyrir vöðvauppbyggingu (Morton o.fl., 2018, BJSM). Sjálfgefið viðmið er 1,8 g/kg og má breyta því.",
  "settings.aboutRules": "Æfingaáætlanir, framvinda og næringarmarkmið byggja á skýrum reglum, án aðkomu gervigreindarþjónustu. Tölurnar hér að neðan eru upphafsviðmið sem má breyta, ekki læknisráðgjöf.",
  "settings.aboutSplits": "Skipting æfingadaga og viðmið fyrir sett og endurtekningar byggja á almennum leiðbeiningum um styrktarþjálfun, meðal annars frá American College of Sports Medicine. Þau fela ekki í sér að ein áætlun sé best fyrir alla.",
  "settings.account": "Reikningur",
