  "settings.analytics": "Deila upplýsingum um notkun appsins",
  "settings.analyticsHint": "Sjálfgefið kveikt. Hjálpar okkur að sjá hvort appið styður við reglulegar æfingar. Skráðir eru nokkrir áfangar, svo sem fyrsta settið, fyrsta lokna æfingin, önnur æfing innan viku, upphaf æfingar og lok uppsetningar, ásamt því hvaða aðgerðir æfingaaðstoðarinnar þú notar. Aðgangur þinn og tímasetning fylgja. Aldrei þyngdir, endurtekningar, æfingar, líkamsmælingar, matur, meiðsli, athugasemdir, spjalltexti, nafn eða netfang. Gögn eru aðeins send meðan innskráning er virk. Slökktu til að stöðva skráningu og eyða ósendum notkunarupplýsingum.",
